const iconPath={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',camera:'<path d="M4 7h4l2-3h4l2 3h4v13H4z"/><circle cx="12" cy="13" r="3.5"/>',shoe:'<path d="m4 5 5 2v5l4 3 7 2v3H3V8zM10 12l3-1m0 4 3-1"/>',shirt:'<path d="m8 4-5 3 3 5 2-1v10h8V11l2 1 3-5-5-3c-1 4-7 4-8 0z"/>',jacket:'<path d="m9 3-5 4-2 11 4 1 2-8v10h8V11l2 8 4-1-2-11-5-4-3 4zM12 7v14"/>',hoodie:'<path d="M8 6c0-6 8-6 8 0l4 3 2 11h-5l-1-7v8H8v-8l-1 7H2L4 9zM8 6l4 3 4-3m-6 10h4"/>',pants:'<path d="M6 3h12l2 18h-6l-2-12-2 12H4zM6 7h12"/>',belt:'<rect x="3" y="8" width="18" height="8" rx="1"/><path d="M8 8v8m5-8v8m-5-4h5m4 0h1"/>',bag:'<path d="M4 8h16l1 13H3zM8 8V6a4 4 0 0 1 8 0v2"/>',bottle:'<path d="M9 3h6v5H9zM7 8h10v13H7zM10 13h4"/>',tech:'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M9 6h6m-4 12h2"/>',other:'<path d="M12 2v20M2 12h20M5 5l14 14M5 19 19 5"/>'};
function svg(name){return `<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPath[name]||iconPath.other}</svg>`}
const categoryIcons=['shoe','shirt','jacket','hoodie','pants','belt','bag','bottle','tech','other'];
function homeCategory(i){return `<a class="home-category" href="/category/${i}/" title="${esc(t(descriptions[i]))}"><span class="category-icon">${svg(categoryIcons[i])}</span><strong>${esc(t(cats[i]))}</strong></a>`}
function renderVIPHome(){
 const chosen=feature(catalog);
 return `<section class="vip-hero"><div class="eyebrow">${tr('LESS SEARCHING. BETTER FINDS.')}</div><h1>CSSBuy <em>Spreadsheet.</em></h1><p>${tr('Find your next favorite. Check the photos. Shop with confidence.')}</p>${search()}<div class="hero-foot"><span>${catalog.length.toLocaleString()} ${esc(t('products'))}</span><span>${tr('10 categories')}</span><span>${tr('Original photos & QC references')}</span></div></section><section class="category-overview"><div class="sectionhead"><h2>${tr('Find your category')}</h2><a class="textlink" href="/categories/">${tr('Browse categories')}</a></div><div class="home-categories">${cats.map((c,i)=>homeCategory(i)).join('')}</div></section><section class="featured-section"><div class="sectionhead"><div><div class="eyebrow">${tr('THE CURRENT EDIT')}</div><h2>${tr('Worth a closer look.')}</h2></div><a class="textlink" href="/spreadsheet/">${tr('View spreadsheet')}</a></div><div class="grid">${chosen.map(card).join('')}</div><div class="full-directory"><p>${tr('Your next find might be one search away.')}</p><a class="primary" href="/spreadsheet/">${tr('Explore the finds')}</a></div></section><section class="order-note"><div><div class="eyebrow">${tr('KNOW THE PROCESS')}</div><h2>${tr('From saved find to your front door.')}</h2><a class="textlink" href="/guide/">${tr('Read the first-order guide')}</a></div><div class="order-path"><div><strong>${tr('Find & compare')}</strong><p>${tr('Check original photos, available styles and reference QC.')}</p></div><div><strong>${tr('Order on CSSBuy')}</strong><p>${tr('Choose your options and confirm the current item price.')}</p></div><div><strong>${tr('Inspect & ship')}</strong><p>${tr('Review your own warehouse photos before arranging delivery.')}</p></div></div></section>${faq()}`;
}
function guideOperationImage(s){
 const frame=null;
 const canvasStyle=frame?`position:absolute;left:${-frame.x/frame.w*100}%;top:${-frame.y/frame.h*100}%;width:${10000/frame.w}%;height:${10000/frame.h}%;`:'';
 const viewportStyle=frame?`aspect-ratio:${s.width*frame.w} / ${s.height*frame.h};`:'';
 return `<a class="guide-image" href="${s.image}" target="_blank" rel="noopener"><span class="guide-image-viewport ${frame?'is-focused':''}" style="${viewportStyle}"><span class="guide-image-canvas" style="${canvasStyle}"><img src="${s.image}" loading="lazy" alt="${esc(lang==='zh-CN'?s.imageTitleZh:t(s.imageTitle))}" width="${s.width}" height="${s.height}">${(s.imageHotspots||[]).map(h=>`<span class="guide-hotspot" aria-hidden="true" style="left:${h.x}%;top:${h.y}%;width:${h.w}%;height:${h.h}%"><span>${esc(h.label)}</span></span>`).join('')}</span></span></a>`;
}
function renderCSSGuide(){
 const zh=lang==='zh-CN',l=(a,b)=>Array.isArray(a)?a.map((v,i)=>zh?b[i]:t(v)):(zh?b:t(a)),mobile=guideDevice()==='mobile';
 const data=mobile?mobileGuideData:guideData;
 if(!data?.steps?.length)return `<div class="empty">${l('The guide could not load. Please reload.','指南未加载，请刷新。')}</div>`;
 return `<div class="hero guide-hero"><div class="eyebrow">${l('THE CSSBUY FIRST-ORDER GUIDE','CSSBuy 首单操作指南')}</div><h1>${l('Your first CSSBuy order.','从选品到收货。')}</h1><p>${l('A practical walkthrough, from the exact item link to warehouse inspection and international delivery.','从核对商品链接，到仓库质检和国际运输的操作说明。')}</p><div class="guide-meta"><span>27 Nov 2026</span><span>${l('Two separate payment stages','商品采购与国际运费分开支付')}</span></div><div class="guide-device-picker" role="group" aria-label="Guide device">${[['auto',l('Auto','自动')],['desktop',l('Computer','电脑')],['mobile',l('Phone','手机')]].map(([m,label])=>`<button type="button" data-guide-device="${m}" aria-pressed="${guideDeviceChoice===m}">${label}</button>`).join('')}</div><p class="guide-device-status" role="status">${mobile?l('Phone guide · independent steps and official mobile app examples.','手机指南 · 独立操作步骤与官方手机应用示例。'):l('Showing computer instructions and official historical desktop illustrations.','当前显示电脑操作说明与官方历史电脑界面示例。')}</p><p class="guide-illustration-note">${mobile?l('Every phone step includes an interface image with the relevant controls highlighted. Site captures and official historical app screens are labelled separately. Entry buttons, forms and payment receipts are different stages; the captions explain exactly what each image shows.','手机每一步均配界面操作图，并标出对应控件。本站手机实拍与官方历史应用图分别注明；入口、表单和付款凭证属于不同阶段，具体以图下注释为准。'):l('Historical desktop examples from CSSBuy’s official Buy For Me guide. Current controls may differ.','配图来自 CSSBuy 官方 Buy For Me 指南的历史电脑界面，当前按钮可能变化。')}</p></div><div class="guide-payment-stages"><div><span>${l('FIRST PAYMENT','第一笔付款')}</span><h2>${l('Buy your items','支付商品采购费用')}</h2><p>${l('Item price, delivery to the warehouse and selected order services.','商品价格、发往仓库的运费及所选订单服务。')}</p></div><div><span>${l('SECOND PAYMENT','第二笔付款')}</span><h2>${l('Ship your parcel','支付国际运费')}</h2><p>${l('After QC: confirm destination, route, packaging and the actual parcel quote.','QC 检查后核对收件地址、线路、包装和实际包裹报价。')}</p></div></div><div class="practical-guide">${data.steps.map((s,i)=>`<article class="practical-step ${mobile?'guide-for-mobile':'guide-for-desktop'}" data-guide-mode="${mobile?'mobile':'desktop'}" id="step-${i+1}"><div class="practical-step-heading"><span class="step-number">${String(i+1).padStart(2,'0')}</span><div><div class="step-location">${esc(l(s.where,s.whereZh))}</div><h2>${esc(l(s.title,s.titleZh))}</h2></div></div><div class="practical-step-grid"><div class="practical-instructions"><ol>${l(s.actions,s.actionsZh).map(a=>`<li>${esc(a)}</li>`).join('')}</ol><div class="continue-check"><strong>${l('Before continuing','继续前核对')}</strong><p>${esc(l(s.check,s.checkZh))}</p></div>${i===0?'<a class="primary" href="https://cssb.uy/2JLm" target="_blank" rel="sponsored noopener">Join CSSBuy</a>':''}</div>${s.image?`<figure class="guide-visual guide-wide"><div class="guide-image-operations"><h3>${esc(l(s.imageTitle,s.imageTitleZh))}</h3><p>${esc(l(s.imageAction,s.imageActionZh))}</p></div>${guideOperationImage(s)}<figcaption>${s.imageCaption?esc(l(s.imageCaption,s.imageCaptionZh)):l('Historical CSSBuy official desktop example. Open image to enlarge.','CSSBuy 官方历史电脑界面示例，点击查看原图。')}</figcaption><div class="guide-image-result"><strong>${l('Check on this screen','本页核对')}</strong><p>${esc(l(s.check,s.checkZh))}</p></div></figure>`:`<div class="guide-capture-note"><p>${mobile?l('Verified phone screenshot pending for this step. Follow the phone instructions beside this note and the current live page.','此步骤已核实的手机截图待补充，请结合本步骤手机说明和当前实际页面操作。'):l('Use the current live CSSBuy page for this action. A verified screenshot for this step has not yet been added.','此步骤以 CSSBuy 当前实际页面为准；已核实的对应截图待补充。')}</p></div>`}</div></article>`).join('')}</div><div class="guide-sources"><h2>${l('Keep the live order details as your reference.','以实际订单页面信息为准。')}</h2><p>${l('An account with an eligible stored item is required for parcel forms. No purchase or payment was made to create this guide.','包裹提交表单需要账号内有可提交的入库商品。本指南制作过程没有下单或付款。')}</p>${mobile?'<a href="https://m.cssbuy.com/appdownload.html" target="_blank" rel="noopener">CSSBuy · Official app examples</a> <a href="https://play.google.com/store/apps/details?id=cn.onebound.cssbuy" target="_blank" rel="noopener">CSSBuy · Publisher screenshots on Google Play</a>':'<a href="https://m.cssbuy.com/buyforme" target="_blank" rel="noopener">CSSBuy · Official Buy For Me guide</a>'}</div>`;
}

// Keep natural card widths while preventing a single card on the final row.
function balanceCategoryRows(){
 const group=document.querySelector('.home-categories');if(!group)return;
 group.querySelector('.category-row-break')?.remove();
 const cards=[...group.querySelectorAll('.home-category')];if(cards.length<3)return;
 const last=cards.at(-1),previous=cards.at(-2),lastTop=last.offsetTop;
 if(cards.filter(card=>card.offsetTop===lastTop).length!==1)return;
 const previousRow=cards.filter(card=>card.offsetTop===previous.offsetTop);
 if(previousRow.length<2)return;
 const gap=parseFloat(getComputedStyle(group).columnGap)||0;
 if(previous.getBoundingClientRect().width+last.getBoundingClientRect().width+gap>group.clientWidth)return;
 const rowBreak=document.createElement('span');rowBreak.className='category-row-break';rowBreak.setAttribute('aria-hidden','true');group.insertBefore(rowBreak,previous);
}
window.addEventListener('resize',balanceCategoryRows);
document.fonts.ready.then(balanceCategoryRows);
